import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import api from '../api/axiosInstance';
import styles from './Auth.module.css';

function getErrorMessage(error, fallbackMessage) {
  if (typeof error.response?.data === 'string') {
    return error.response.data;
  }

  return error.response?.data?.message || fallbackMessage;
}

export default function ForgotPassword() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    username: '',
    otpCode: '',
    newPassword: '',
    confirmPassword: '',
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [otpLoading, setOtpLoading] = useState(false);
  const [resetLoading, setResetLoading] = useState(false);

  const handleChange = (event) => {
    setForm({ ...form, [event.target.name]: event.target.value });
  };

  const handleSendOtp = async () => {
    if (!form.username.trim()) {
      setError('Username is required to request an OTP.');
      setSuccess('');
      return;
    }

    setError('');
    setSuccess('');
    setOtpLoading(true);

    try {
      const response = await api.post('/forgot-password', {
        username: form.username.trim(),
      });
      setSuccess(response.data || 'OTP has been successfully sent.');
    } catch (requestError) {
      setError(getErrorMessage(requestError, 'Unable to send OTP. Please try again.'));
    } finally {
      setOtpLoading(false);
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError('');
    setSuccess('');
    setResetLoading(true);

    try {
      const payload = {
        ...form,
        username: form.username.trim(),
        otpCode: form.otpCode.trim(),
      };

      const response = await api.post('/reset-password', payload);
      setSuccess(response.data || 'Password reset successfully.');
      navigate('/login');
    } catch (requestError) {
      setError(getErrorMessage(requestError, 'Password reset failed. Please try again.'));
    } finally {
      setResetLoading(false);
    }
  };

  return (
    <div className={styles.container}>
      <div className={styles.card}>
        <h2 className={styles.title}>Forgot Password</h2>
        <p className={styles.helper}>
          Request a one-time password with your username, then submit the OTP with your new password.
        </p>
        {error && <p className={styles.error}>{error}</p>}
        {success && <p className={styles.success}>{success}</p>}
        <form onSubmit={handleSubmit} className={styles.form}>
          <label>Username</label>
          <input
            name="username"
            type="text"
            value={form.username}
            onChange={handleChange}
            placeholder="Enter username"
            autoComplete="username"
            required
          />
          <button
            type="button"
            className={styles.secondaryButton}
            onClick={handleSendOtp}
            disabled={otpLoading || resetLoading}
          >
            {otpLoading ? 'Sending OTP...' : 'Send OTP'}
          </button>

          <h3 className={styles.sectionTitle}>Reset Password</h3>

          <label>OTP Code</label>
          <input
            name="otpCode"
            type="text"
            value={form.otpCode}
            onChange={handleChange}
            placeholder="Enter 6-digit OTP"
            inputMode="numeric"
            maxLength={6}
            required
          />

          <label>New Password</label>
          <input
            name="newPassword"
            type="password"
            value={form.newPassword}
            onChange={handleChange}
            placeholder="Enter new password"
            autoComplete="new-password"
            required
          />

          <label>Confirm Password</label>
          <input
            name="confirmPassword"
            type="password"
            value={form.confirmPassword}
            onChange={handleChange}
            placeholder="Confirm new password"
            autoComplete="new-password"
            required
          />

          <button type="submit" disabled={otpLoading || resetLoading}>
            {resetLoading ? 'Resetting Password...' : 'Reset Password'}
          </button>
        </form>
        <p className={styles.link}>
          Remembered your password? <Link to="/login">Back to Login</Link>
        </p>
      </div>
    </div>
  );
}
